<script setup>
import {renewalNoticeState} from '../utils/renewalNotice.js';
import AppDialog from './AppDialog.vue';
import {computed,ref} from 'vue';import axios from 'axios';import {bookingNow} from '../utils/bookingClock.js';import {ownerTimestamp,ownerDate} from '../utils/ownerBookingDisplay.js';
const props=defineProps({booking:Object,owner:Boolean});const emit=defineEmits(['changed','notice']);const dialogOpen=ref(false),action=ref('leave'),months=ref(1),busy=ref(false),error=ref('');
const state=computed(()=>renewalNoticeState(props.booking,bookingNow().getTime()));
const waiting=computed(()=>state.value.waiting),open=computed(()=>state.value.open);
const choose=value=>{action.value=value;error.value='';dialogOpen.value=true};
const save=async()=>{if(busy.value)return;busy.value=true;error.value='';try{const {data}=await axios.post(action.value==='leave'?'/api/student/bookings/renewal/'+props.booking.id:'/api/student/bookings/extend/'+props.booking.id,action.value==='leave'?{choice:'leave'}:{extension_months:Number(months.value)},{headers:{Authorization:'Bearer '+sessionStorage.getItem('cspc_token')}});dialogOpen.value=false;emit('notice',data.message || 'Extension requested. Owner approval is still required; your booked checkout has not changed.');emit('changed');}catch(e){error.value=e.response?.data?.message || 'Could not save your decision. Refresh and try again.';}finally{busy.value=false;}};
</script>
<template><section v-if="state.visible" :class="['renewal-notice',{'is-info':!waiting && !open}]">
<template v-if="waiting"><h3>Waiting for a resident's decision</h3><p>A bed for these dates depends on a current resident leaving rather than extending their stay. <template v-if="booking.renewal_departure_dates?.length">Their planned checkout: <strong>{{ booking.renewal_departure_dates.map(ownerDate).join(", ") }}</strong>. </template>The resident must give their decision by <strong>{{ ownerTimestamp(booking.renewal_wait_until) }}</strong>.</p><p>{{ owner ? "This request is not approved yet. Wait for the resident decision before reviewing the replacement request. Actual checkout must still be recorded when the resident leaves." : "Your request is not approved yet. No payment is due. Wait for a notification: if the resident leaves as planned, the owner can review your request; if they extend and no bed remains, your request will close. You may then choose another room or different dates." }}</p></template>
<template v-else-if="state.departure"><h3>Departure planned for {{ ownerDate(state.checkout) }}</h3><p>{{ owner ? 'The resident confirmed they plan to leave on this date. You can review a future request if its dates fit. Record actual checkout after the resident leaves; the next stay cannot start until a bed is released.' : 'You confirmed you plan to leave on this date. Your current stay remains active. Arrange departure with the owner, who must record your actual checkout.' }}</p></template>
<template v-else><h3>{{ state.pendingExtension ? 'Extension awaiting owner approval' : 'Will you extend your stay?' }}</h3><p>Current checkout: <strong>{{ ownerDate(state.checkout) }}</strong>. {{ state.pendingExtension ? (owner ? 'The resident checkout changes only after you approve the extension.' : 'Your checkout date changes only after the owner approves the extension.') : 'Another request depends on a bed becoming available after this date.' }}</p><p v-if="open">{{ owner ? 'Review this resident decision and any extension request' : 'Confirm leaving or request an extension' }} by <strong>{{ ownerTimestamp(booking.renewal_response_due_at) }}</strong>. An extension must be approved before this deadline to keep renewal priority.</p><p v-else-if="state.pendingExtension">The extension request is still pending. Owner approval depends on available dates; it cannot displace an already approved reservation.</p><div v-if="!owner && open && !state.pendingExtension" class="renewal-actions"><button @click="choose('extend')" type="button">Request extension</button><button @click="choose('leave')" type="button">Confirm leaving as scheduled</button></div></template>
</section>
<AppDialog :open="dialogOpen" :title="action==='leave'?'Confirm departure intention?':'Request stay extension?'" :icon="action==='leave'?'fa-person-walking-luggage':'fa-calendar-plus'" tone="info" :busy="busy" @close="dialogOpen=false">
 <template v-if="action==='leave'"><p class="app-dialog-lead">This records that you plan to leave on your booked checkout date, <strong>{{ ownerDate(state.checkout) }}</strong>.</p><dl class="app-dialog-facts"><div><dt>Current stay</dt><dd>Stays active; you are not checked out</dd></div><div><dt>Replacement requests</dt><dd>The owner may review them</dd></div><div><dt>Later extensions</dt><dd>Depend on remaining availability</dd></div></dl></template>
 <template v-else><p class="app-dialog-lead">The owner must approve your extension. Until then, your booked checkout stays <strong>{{ ownerDate(state.checkout) }}</strong>.</p><p class="app-dialog-callout"><i class="fa-solid fa-circle-info" aria-hidden="true"></i><span>Approval must happen before the renewal deadline to keep your renewal priority.</span></p><label class="app-dialog-field">Additional months<input v-model="months" type="number" min="1" max="120" step="1"></label></template>
 <p v-if="error" role="alert" class="app-dialog-error">{{ error }}</p>
 <template #footer><button type="button" class="app-btn secondary" :disabled="busy" @click="dialogOpen=false">Go back</button><button type="button" class="app-btn primary" :disabled="busy || (action==='extend' && (!Number.isInteger(Number(months)) || Number(months)<1))" @click="save">{{ busy?'Saving...':action==='leave'?'Confirm leaving':'Submit extension request' }}</button></template>
</AppDialog></template>
<style scoped>.renewal-notice{margin:16px 0;padding:16px;background:#fff9ed;border:1px solid #f6dfb6;border-radius:12px;color:#654b25;font-size:13px;line-height:1.65}.renewal-notice h3{font-size:14px;font-weight:650;margin:0 0 8px}.renewal-notice p{margin:7px 0}.renewal-actions,.renewal-dialog footer{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.renewal-notice button,.renewal-dialog button{font:inherit;font-size:12px;font-weight:600;border:1px solid #cdd9e8;background:white;color:#215bcc;border-radius:8px;padding:8px 12px;cursor:pointer}.renewal-dialog{width:min(480px,calc(100vw - 32px));box-sizing:border-box;border:0;border-radius:16px;padding:24px;color:#233e60;box-shadow:0 24px 70px #10274433}.renewal-dialog::backdrop{background:#0f172a80}.renewal-dialog h2{font-size:18px;font-weight:650;margin:0 0 12px}.renewal-dialog p{font-size:13px;line-height:1.65}.renewal-dialog label{display:grid;gap:8px;font-size:13px;margin-top:16px}.renewal-dialog input{padding:10px;border:1px solid #cdd9e8;border-radius:8px;font:inherit}.renewal-dialog footer{justify-content:flex-end}.renewal-dialog .primary{color:white;background:#2563eb;border-color:#2563eb}.renewal-dialog .error{color:#b42338}.renewal-dialog button:disabled{opacity:.5;cursor:not-allowed}@media(pointer:coarse){button{min-height:44px}}</style>
<style scoped>.renewal-notice.is-info{background:#f3f8ff;border-color:#d7e5fa;color:#294a70}</style>
